document.querySelectorAll(".agent-carousel-shell").forEach((shell) =>{const carousel = shell.querySelector(".agent-carousel");const previous = shell.querySelector("[data-carousel-prev]");const next = shell.querySelector("[data-carousel-next]");if (!carousel || !previous || !next) return;const updateControls = () =>{const maxScroll = carousel.scrollWidth - carousel.clientWidth;previous.disabled = carousel.scrollLeft <= 2;next.disabled = carousel.scrollLeft >= maxScroll - 2;};const move = (direction) =>{carousel.scrollBy({left:direction * carousel.clientWidth,behavior:window.matchMedia("(prefers-reduced-motion:reduce)").matches ? "auto":"smooth",});};previous.addEventListener("click",() => move(-1));next.addEventListener("click",() => move(1));carousel.addEventListener("scroll",updateControls,{passive:true});window.addEventListener("resize",updateControls);updateControls();});document.addEventListener("click",(event) =>{document.querySelectorAll(".site-nav-dropdown[open]").forEach((dropdown) =>{if (!dropdown.contains(event.target)) dropdown.removeAttribute("open");});});